_st = {'ph': 'fwd', 'ft': 0.0}
def control(obs):
    h = obs.get('hitch_deg', 0.0)
    dt = obs.get('dt', 0.1)
    st = obs.get('status', '')
    m = obs.get('motion') or {}
    hold = m.get('hold_s', 0.0) or 0.0
    if st in ('PINNED', 'JACKKNIFED'):
        _st['ph'] = 'fwd'
        _st['ft'] = 0.0
    if _st['ph'] == 'fwd':
        if hold > 0:
            return (0.0, 0.0)
        _st['ft'] += dt
        if _st['ft'] < 3.0:
            return (0.0, 0.6)
        _st['ph'] = 'rev'
    s = 4.0 * (h + 1.5)
    s = max(-34.0, min(34.0, s))
    return (s, -0.4)

